import "./App.css";
import Stopwatch from "./Stopwatch.tsx";

function App() {
  const genders = [{ m: "Homme" }, { f: "Femme" }, { nb: "Non-Binaire" }];
  return (
    <div className="App">
      {Object.keys(genders).map((gender) => (
        <Stopwatch genderId={gender} display={genders.gender} key={gender} />
      ))}
    </div>
  );
}

export default App;
